def maxRobotsWithinBudget(charge, running, budget):
    from collections import deque
    dq = deque()
    left = 0
    total = 0
    best = 0
    for r in range(len(charge)):
        while dq and charge[dq[-1]] <= charge[r]:
            dq.pop()
        dq.append(r)
        total += running[r]
        while left <= r and charge[dq[0]] + (r - left + 1) * total > budget:
            total -= running[left]
            if dq[0] == left:
                dq.popleft()
            left += 1
            if left > r:
                dq.clear()
        best = max(best, r - left + 1)
    return best
